xml.Script:
        Colors[ 0] := 'FFFFFF'; // White
        Colors[ 1] := 'FFFF00'; // Yellow
        Colors[ 2] := '0000CC'; // Blue
        Colors[ 3] := 'FF0000'; // Red
        Colors[ 4] := '00AA00'; // Green
        Colors[ 5] := 'AA00AA'; // Violett
        Colors[ 6] := 'FFFFAA'; // Cream
        Colors[ 7] := '0066CC'; // LightBlue
        Colors[ 8] := 'FF6000'; // Orange
        Colors[ 9] := '00FF00'; // LightGreen
        Colors[10] := 'FF88CC'; // LightViolett
        Colors[11] := '666666'; // Gray

        R := 0.7;
        include 'Figures\Scripts\Dodecahedron_Coordinates.inc';

        D := R / 0.7 * 0.45407;

        k := 1.15;
        for i := 0 to 11 do begin
            Ckx[i] := Cx[i] * k;
            Cky[i] := Cy[i] * k;
            Ckz[i] := Cz[i] * k;
        end;

        for i := 0 to 4 do begin
            ax[i] := sin(2*Pi/5 * i);
            ay[i] := cos(2*Pi/5 * i);
        end;
        az := sin(Pi/5);

        // Calcs angle from 2 to 3 while rotating over 1
        function Angle(x1, y1, z1, x2, y2, z2, x3, y3, z3);
        begin
          vx1 := y1 * z2 - y2 * z1;
          vy1 := z1 * x2 - z2 * x1;
          vz1 := x1 * y2 - x2 * y1;
          wx := y1 * z3 - y3 * z1;
          wy := z1 * x3 - z3 * x1;
          wz := x1 * y3 - x3 * y1;
          Result := ArcCos((vx1*wx + vy1*wy + vz1*wz) / (vx1^2 + vy1^2 + vz1^2));
        end;

        A1 := Angle(ax[0], ay[0], az, ax[2], ay[2],  az, ax[3], ay[3], az);
        A2 := Angle(ax[0], ay[0], az, ax[0], ay[0], -az, ax[1], ay[1], az);
        A3 := Angle(ax[0], ay[0], az, ax[1], ay[1],  az, ax[4], ay[4], az);
